// Package intents is the Phase 1 capability registry derived from the Genie
// scenario catalogue (specs/catalogue/genie-catalogue/Scenarios.csv).
// catalog_gen.go is generated by scripts/gen-intents.
package intents

import (
	"regexp"
	"sort"
	"strings"
)

// Requirement is one Module → Feature → Permission check from the catalogue.
// Optional requirements gate extra content (e.g. KPI tiles) or are alternatives.
type Requirement struct {
	Module     string `json:"module"`
	Feature    string `json:"feature"`
	Permission string `json:"permission"`
	Optional   bool   `json:"optional,omitempty"`
}

// Intent is one catalogue scenario.
type Intent struct {
	ScenarioID   string        `json:"scenarioId"`
	ID           string        `json:"id"`
	Module       string        `json:"module"`
	Category     string        `json:"category"`
	Examples     []string      `json:"examples"`
	Handling     string        `json:"handling"`
	UserSees     string        `json:"userSees"`
	ResponseType string        `json:"responseType"`
	Scope        string        `json:"scope"`
	Priority     string        `json:"priority"`
	RBAC         string        `json:"rbac"`
	Requirements []Requirement `json:"requirements"`
}

// Response types used in the catalogue.
const (
	RTData         = "Data card"
	RTList         = "List card"
	RTNavigate     = "Navigate (deep link)"
	RTGuide        = "Guide + citation"
	RTText         = "Text answer"
	RTComparison   = "Comparison card"
	RTChecklist    = "Checklist / readiness card"
	RTClarify      = "Clarifying question"
	RTDenied       = "Denied (RBAC)"
	RTNotSupported = "Not supported (captured)"
	RTDisambiguate = "Disambiguation"
	UnsupportedID  = "unsupported"
	SmallTalkID    = "smalltalk"
)

var (
	byID    = map[string]Intent{}
	ordered []Intent // unique by ID, catalogue order
)

func init() {
	for _, it := range Catalog {
		if prev, ok := byID[it.ID]; ok {
			// Same capability in several scenarios (e.g. guide_query): merge examples,
			// keep the higher priority row's metadata.
			prev.Examples = append(prev.Examples, it.Examples...)
			if it.Priority < prev.Priority {
				ex := prev.Examples
				prev = it
				prev.Examples = ex
			}
			byID[it.ID] = prev
			continue
		}
		byID[it.ID] = it
		ordered = append(ordered, it)
	}
	for i := range ordered {
		ordered[i] = byID[ordered[i].ID]
	}
}

// Get returns the intent for a capability id.
func Get(id string) (Intent, bool) {
	it, ok := byID[id]
	return it, ok
}

// All returns unique intents in catalogue order.
func All() []Intent { return append([]Intent(nil), ordered...) }

var wordRe = regexp.MustCompile(`[a-z0-9]+`)

var stop = map[string]bool{"the": true, "a": true, "an": true, "is": true, "of": true, "for": true, "to": true, "me": true, "my": true, "and": true, "in": true, "on": true, "what": true, "do": true, "we": true, "i": true, "you": true, "it": true, "are": true, "how": true, "show": true, "s": true}

func words(s string) map[string]bool {
	out := map[string]bool{}
	for _, w := range wordRe.FindAllString(strings.ToLower(s), -1) {
		if !stop[w] && len(w) > 1 {
			out[strings.TrimSuffix(w, "s")] = true
		}
	}
	return out
}

// Match is a keyword-scored intent candidate.
type Match struct {
	Intent Intent
	Score  float64
}

// KeywordMatch is the deterministic fallback classifier (used when the LLM is
// unavailable): Jaccard-like overlap between the message and each intent's
// examples + id words.
func KeywordMatch(message string, n int) []Match {
	q := words(message)
	if len(q) == 0 {
		return nil
	}
	var out []Match
	for _, it := range ordered {
		best := 0.0
		cands := append([]string{strings.ReplaceAll(it.ID, "_", " ")}, it.Examples...)
		for _, ex := range cands {
			e := words(ex)
			if len(e) == 0 {
				continue
			}
			hit := 0
			for w := range q {
				if e[w] {
					hit++
				}
			}
			s := float64(hit) / float64(len(q)+len(e)-hit)
			if s > best {
				best = s
			}
		}
		if best > 0 {
			out = append(out, Match{it, best})
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].Score > out[j].Score })
	if len(out) > n {
		out = out[:n]
	}
	return out
}
